import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import {
  exportActivity,
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IssueId, ProjectId, IsoTimestamp } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let detach: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("scratch", "growth");
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("scratch audit checks", () => {
  it("names the assigner, keeps the backdated time, and filters by project", async () => {
    const projectA = "PROJ-A" as ProjectId;
    const projectB = "PROJ-B" as ProjectId;
    const backdated = "2026-01-05T08:00:00.000Z" as IsoTimestamp;

    await emit("issue.assigned", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: backdated,
      issueId: "ISSUE-1" as IssueId,
      projectId: projectA,
      previousAssigneeId: null,
      assigneeId: tenant.userIds.member,
    });
    await emit("issue.status_changed", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: backdated,
      issueId: "ISSUE-1" as IssueId,
      projectId: projectA,
      from: "todo",
      to: "done",
    } as never);
    await emit("issue.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: backdated,
      issueId: "ISSUE-2" as IssueId,
      projectId: projectB,
      title: "Other",
      assigneeId: null,
      priority: "low",
    } as never);

    const assigned = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issue.assigned"],
      limit: 25,
      cursor: null,
    });
    expect(assigned.items[0]?.actorId).toBe(tenant.userIds.admin);
    expect(assigned.items[0]?.occurredAt).toBe(backdated);

    const inA = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: projectA,
      limit: 25,
      cursor: null,
    });
    expect(inA.items.map((e) => e.action).sort()).toEqual([
      "issue.assigned",
      "issue.status_changed",
    ]);
    const status = inA.items.find((e) => e.action === "issue.status_changed");
    expect(status?.metadata).toEqual({ from: "todo", to: "done" });
  });

  it("records comment events against the issue's project", async () => {
    // Comment events name only the issue; the project is looked up from it,
    // so no real issue row means no project and the entry is still written.
    await emit("comment.updated", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: tenant.org.createdAt,
      commentId: "CMT-1" as CommentId,
      issueId: "ISSUE-missing" as IssueId,
    });
    const page = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["comment.updated"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]?.projectId).toBeNull();
  });

  it("exports every entry in range, with inclusive ends and details", async () => {
    const at = "2026-03-01T12:00:00.000Z" as IsoTimestamp;
    for (let i = 0; i < 130; i++) {
      await emit("project.created", {
        orgId: tenant.org.id,
        actorId: tenant.userIds.admin,
        occurredAt: at,
        projectId: `P-${i}` as ProjectId,
        name: `Bulk ${i}`,
        slug: `bulk-${i}`,
      });
    }

    const json = JSON.parse(
      await exportActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        since: at,
        until: at,
        format: "json",
      }),
    ) as Array<{ occurredAt: string; action: string }>;
    expect(json.length).toBe(130);
    expect(new Set(json.map((e) => e.action))).toEqual(new Set(["project.created"]));

    // Same instant written with different fractional-second spelling still matches.
    const spelled = JSON.parse(
      await exportActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        since: "2026-03-01T12:00:00Z" as IsoTimestamp,
        until: "2026-03-01T12:00:00Z" as IsoTimestamp,
        format: "json",
      }),
    ) as unknown[];
    expect(spelled.length).toBe(130);

    const csv = await exportActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      since: at,
      until: at,
      format: "csv",
    });
    expect(csv.split("\r\n").length).toBe(131);
  });

  it("refuses a range that ends before it starts", async () => {
    await expect(
      exportActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        since: "2026-03-02T00:00:00.000Z" as IsoTimestamp,
        until: "2026-03-01T00:00:00.000Z" as IsoTimestamp,
        format: "json",
      }),
    ).rejects.toThrow();
  });
});

